"""
    Returns a string representation of the ordinal number for `n`

    e.g.,
    >>> ordinal_number(1)
    '1st'
    >>> ordinal_number(4)
    '4th'
    >>> ordinal_number(21)
    '21st'
    """
def ordinal_number(n: int) -> object {
    return (
        '%d%s'
        % (n, 'tsnrhtdd'[((((n // 10) % 10) != 1) * ((n % 10) < 4) * (n % 10))::4])
    );
}

"""
    special find and replace function
    to clean up line endings in the file
    from end or starttag characters
    """
def find_replace_line_endings(fp_readlines: Any) -> object {
    clean = [];
    for line in fp_readlines {
        if line.endswith("=<\n") {
            line = line.replace("<\n", "lt\n");
        }
        clean.append(line);
    }
    return "".join(clean);
}

